import openpyxl
from openpyxl.utils import get_column_letter

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task']

# Verify formulas exist and start with '='
target_ranges=[]
# H12:L17 etc
for r in range(12,18):
    for c in range(8,13):
        target_ranges.append((r,c))
for r in range(19,25):
    for c in range(8,13):
        target_ranges.append((r,c))
for r in range(26,32):
    for c in range(8,13):
        target_ranges.append((r,c))
for r in range(35,41):
    for c in range(8,13):
        target_ranges.append((r,c))
for r in range(42,48):
    for c in range(8,13):
        target_ranges.append((r,c))
for c in range(8,13):
    target_ranges.append((50,c))

bad=[]
empty=[]
for r,c in target_ranges:
    v=ws.cell(r,c).value
    addr=f'{get_column_letter(c)}{r}'
    if v is None:
        empty.append(addr)
    elif not (isinstance(v,str) and v.startswith('=')):
        bad.append((addr,v))

print('Total target cells:', len(target_ranges))
print('Empty:', len(empty))
if empty:
    print('Empty addrs:', empty[:20])
print('Non-formula / bad:', len(bad))
if bad:
    print('Bad samples:', bad[:10])

# Print samples
sample_addrs=['H12','I12','H19','H26','H35','H42','H46','H50','L50']
print('\nSample formulas:')
for a in sample_addrs:
    print(a, ws[a].value)

# Confirm labels align
print('\nStat labels (E42:E47):', [ws[f'E{r}'].value for r in range(42,48)])

